#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { access, mkdir, mkdtemp, readdir, readFile, realpath, rename, rm } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { build } from "esbuild";

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const distDirectory = join(packageRoot, "dist");
const GENERATED_BANNER = [
  "// @generated by scripts/build-runtime.mjs; do not edit.",
  "// @ts-nocheck -- generated JavaScript uses a .ts extension for Pi's Jiti loader.",
].join("\n");

const FORBIDDEN_EAGER_INPUTS = [
  "src/sync/setup-switch.ts",
  "src/sync/sync-operations.ts",
  "src/sync/sync-queries.ts",
  "src/sync/sync-inspection.ts",
  "src/sync/sync-mutations.ts",
  "src/ui/manager-ui.ts",
  "src/ui/setup/setup-wizard.ts",
  "src/ui/setup/setup-switcher.ts",
  "src/ui/setup/setup-actions.ts",
  "src/ui/setup/s3-ui.ts",
  "src/ui/setup/setup-location-ui.ts",
  "src/ui/manager-result-dispatcher.ts",
  "src/ui/file-selection.ts",
  "src/ui/remote-selection-ui.ts",
  "src/backends/s3/s3-backend.ts",
  "src/backends/webdav/webdav-backend.ts",
  "src/backends/git/git-backend.ts",
];
const FORBIDDEN_EAGER_EXTERNALS = ["@narumitw/pi-tui-kit", "fast-xml-parser"];

export async function buildRuntime({ outputDirectory = distDirectory, validateOutput = validateGeneratedFiles } = {}) {
  const resolvedOutputDirectory = resolve(outputDirectory);
  await assertSafeOutputDirectory(resolvedOutputDirectory);
  await mkdir(dirname(resolvedOutputDirectory), { recursive: true });
  const stagingDirectory = await mkdtemp(join(dirname(resolvedOutputDirectory), ".pi-sync-dist-"));

  try {
    const result = await build({
      absWorkingDir: packageRoot,
      banner: { js: GENERATED_BANNER },
      bundle: true,
      chunkNames: "chunks/[name]-[hash]",
      entryNames: "index",
      entryPoints: ["src/index.ts"],
      format: "esm",
      legalComments: "none",
      metafile: true,
      outExtension: { ".js": ".ts" },
      outdir: stagingDirectory,
      packages: "external",
      platform: "node",
      sourcemap: true,
      splitting: true,
      target: "es2022",
      write: true,
    });
    validateEagerGraph(result.metafile);
    await validateOutput(stagingDirectory);
    await publishRuntime(stagingDirectory, resolvedOutputDirectory);
    return result.metafile;
  } catch (error) {
    await rm(stagingDirectory, { force: true, recursive: true });
    throw error;
  }
}

export function validateEagerGraph(metadata) {
  const outputs = metadata.outputs ?? {};
  const entry = Object.entries(outputs).find(([, output]) =>
    normalizePath(output.entryPoint ?? "").endsWith("/src/index.ts"),
  );
  if (!entry) throw new Error("Generated runtime metadata has no src/index.ts entrypoint");

  const allInputs = new Set();
  for (const output of Object.values(outputs)) {
    for (const inputPath of Object.keys(output.inputs ?? {})) {
      const normalized = normalizePath(inputPath);
      allInputs.add(normalized);
      if (normalized.includes("/node_modules/")) {
        throw new Error(`Bundled package input: ${normalized}`);
      }
    }
  }

  const eagerOutputs = collectEagerOutputs(outputs, entry[0]);
  const eagerInputs = new Set();
  for (const outputPath of eagerOutputs) {
    const output = outputs[outputPath];
    if (!output) continue;
    for (const inputPath of Object.keys(output.inputs ?? {})) {
      eagerInputs.add(normalizePath(inputPath));
    }
    for (const imported of output.imports ?? []) {
      if (
        imported.external &&
        FORBIDDEN_EAGER_EXTERNALS.some(
          (dependency) => imported.path === dependency || imported.path.startsWith(`${dependency}/`),
        )
      ) {
        throw new Error(`Eager external dependency: ${imported.path} from ${normalizePath(outputPath)}`);
      }
    }
  }

  for (const forbidden of FORBIDDEN_EAGER_INPUTS) {
    if (!allInputs.has(`/${forbidden}`)) {
      throw new Error(`First-use implementation is missing from build inputs: ${forbidden}`);
    }
    if (eagerInputs.has(`/${forbidden}`)) {
      throw new Error(`First-use implementation is eager: ${forbidden}`);
    }
  }
  return { eagerInputs, eagerOutputs };
}

export async function validateGeneratedFiles(outputDirectory) {
  const files = await listFiles(outputDirectory);
  const runtimeFiles = files.filter((path) => path.endsWith(".ts"));
  if (!runtimeFiles.includes("index.ts")) {
    throw new Error("Generated runtime is missing index.ts");
  }
  if (!runtimeFiles.some((path) => path.startsWith("chunks/"))) {
    throw new Error("Generated runtime has no lazy chunks");
  }

  // Parse emitted JavaScript with the existing bundler rather than matching import-like text.
  // Non-bundling mode inventories static re-exports and dynamic imports without resolving them.
  const parsed = await build({
    entryPoints: runtimeFiles.map((file) => resolve(outputDirectory, file)),
    outdir: resolve(outputDirectory, ".validation"),
    bundle: false,
    format: "esm",
    platform: "node",
    metafile: true,
    write: false,
  });
  for (const output of Object.values(parsed.metafile.outputs)) {
    for (const imported of output.imports) {
      if (!imported.path.startsWith("./") && !imported.path.startsWith("../")) continue;
      const target = relative(
        resolve(outputDirectory),
        resolve(dirname(resolve(output.entryPoint)), imported.path),
      ).replaceAll("\\", "/");
      if (!runtimeFiles.includes(target)) {
        throw new Error(
          `Generated relative import has no exact runtime target: ${imported.path} from ${output.entryPoint}`,
        );
      }
    }
  }

  for (const runtimePath of runtimeFiles) {
    const source = await readFile(join(outputDirectory, runtimePath), "utf8");
    if (!source.startsWith(GENERATED_BANNER)) {
      throw new Error(`Generated marker is missing from ${runtimePath}`);
    }
    if (/["']\.\.?\/[^"']+\.js["']/u.test(source)) {
      throw new Error(`Generated runtime retains a .js import specifier in ${runtimePath}`);
    }
    if (/["']\.\.?\/[^"']*src\//u.test(source)) {
      throw new Error(`Generated runtime imports authoritative source from ${runtimePath}`);
    }
    if (!files.includes(`${runtimePath}.map`)) {
      throw new Error(`Source map is missing for ${runtimePath}`);
    }
  }
}

async function assertSafeOutputDirectory(outputDirectory) {
  const relativeOutput = relative(packageRoot, outputDirectory);
  const firstSegment = relativeOutput.split(sep)[0];
  const isDefaultOutput = relativeOutput === "dist";
  const isTestOutput = firstSegment?.startsWith(".pi-sync-build-test-");
  if (
    relativeOutput === "" ||
    relativeOutput === ".." ||
    relativeOutput.startsWith(`..${sep}`) ||
    isAbsolute(relativeOutput) ||
    (!isDefaultOutput && !isTestOutput)
  ) {
    throw new Error("Runtime output directory must be inside the package root and owned by the build");
  }

  const realPackageRoot = await realpath(packageRoot);
  const realOutputParent = await realpath(dirname(outputDirectory));
  const relativeParent = relative(realPackageRoot, realOutputParent);
  if (relativeParent === ".." || relativeParent.startsWith(`..${sep}`) || isAbsolute(relativeParent)) {
    throw new Error("Runtime output parent must not escape the package root through a symlink");
  }
}

function collectEagerOutputs(outputs, entryPath) {
  const eager = new Set();
  const pending = [entryPath];
  while (pending.length > 0) {
    const outputPath = pending.pop();
    if (!outputPath || eager.has(outputPath)) continue;
    eager.add(outputPath);
    for (const imported of outputs[outputPath]?.imports ?? []) {
      if (imported.external || imported.kind === "dynamic-import") continue;
      if (outputs[imported.path]) pending.push(imported.path);
    }
  }
  return eager;
}

async function publishRuntime(stagingDirectory, outputDirectory) {
  const backupDirectory = `${outputDirectory}.backup-${randomUUID()}`;
  const hadPreviousOutput = await exists(outputDirectory);
  if (hadPreviousOutput) await rename(outputDirectory, backupDirectory);
  try {
    await rename(stagingDirectory, outputDirectory);
  } catch (error) {
    if (hadPreviousOutput) {
      await rm(outputDirectory, { force: true, recursive: true });
      await rename(backupDirectory, outputDirectory);
    }
    throw error;
  }
  if (hadPreviousOutput) await rm(backupDirectory, { force: true, recursive: true });
}

async function exists(path) {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

async function listFiles(directory, prefix = "") {
  const files = [];
  for (const entry of await readdir(join(directory, prefix), { withFileTypes: true })) {
    const relativePath = join(prefix, entry.name);
    if (entry.isDirectory()) files.push(...(await listFiles(directory, relativePath)));
    else if (entry.isFile()) files.push(relativePath.replaceAll("\\", "/"));
  }
  return files.sort();
}

function normalizePath(path) {
  const normalized = path.replaceAll("\\", "/");
  if (!isAbsolute(path)) return `/${normalized.replace(/^\.\//u, "")}`;
  return `/${relative(packageRoot, path).replaceAll("\\", "/")}`;
}

const invokedPath = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : undefined;
if (invokedPath === import.meta.url) await buildRuntime();
